# Experiment 3B: create and export the student-score dataset.
students<-data.frame(Student=c("Srinivas","Siva","Naveen","Srinath","Ganesh","Anil","Deep","Radhakrishna","Kiran","Harsha"),Math=c(82,72,91,65,78,85,60,95,70,83),Science=c(90,82,76,88,72,80,91,85,94,80),English=c(91,78,89,88,86,87,83,92,97,90),Age=c(17,18,16,19,17,18,16,19,17,18),Hours_Studied=c(3,4,5,7,8,10,2,4,5,6)); stopifnot(!anyDuplicated(students$Student),all(unlist(students[c("Math","Science","English")])%in%0:100))
args<-commandArgs(FALSE); f<-grep("^--file=",args,value=TRUE); root<-if(length(f))dirname(dirname(normalizePath(sub("^--file=","",f[1])))) else normalizePath("."); dest<-file.path(root,"data","student_scores.csv"); dir.create(dirname(dest),recursive=TRUE,showWarnings=FALSE); write.csv(students,dest,row.names=FALSE); print(students); cat("Saved:",dest,"\n")
